#!/data/data/com.termux/files/usr/bin/bash
# ESPIAO MID5 v6 — espio em Python puro (sem mitmproxy, sem rust, funciona em 32 bits)
B='\033[1m'; G='\033[32m'; Y='\033[33m'; C='\033[36m'; R='\033[31m'; N='\033[0m'
clear
echo -e "${C}${B}"
echo "  =============================="
echo "   ESPIAO MID5 v6 — Rzim FF2023"
echo "  =============================="
echo -e "${N}"

command -v python3 >/dev/null 2>&1 || pkg install -y python >/dev/null 2>&1
python3 -c "import cryptography" 2>/dev/null || pkg install -y python-cryptography >/dev/null 2>&1
python3 -c "import cryptography" 2>/dev/null || { echo -e "${R}[X] Roda na mao: pkg install python-cryptography -y"; exit 1; }

mkdir -p $HOME/.mitmproxy
echo "" | base64 -d > $HOME/.mitmproxy/mitmproxy-ca.pem
echo "" | base64 -d > $HOME/ff2023_spy6.py

echo -e "${G}[*] Espiao LIGADO"
echo -e "${B}[*] Abre o ${G}Spy_MID5${N}${B} e aperta em TUDO"
echo -e "${B}[*] Acabou? ${Y}Ctrl+C${N}${B} aqui"
echo ""
rm -f $HOME/ff2023_captura.jsonl
python3 $HOME/ff2023_spy6.py
echo ""
echo -e "${G}[i] Gravou ff2023_captura.jsonl! Manda pro Elio no WhatsApp."
